using HKX2E;
using System.IO;
using System.Numerics;
using System.Text.Json;
using System.Security.Cryptography;
namespace DanceStudio;
public static class PreservationTests {
 public static void Run(string projectFile,string output){
  Directory.CreateDirectory(output);int checks=0;
  void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}
  void Reject(Action action,string why){bool failed=false;try{action();}catch{failed=true;}Check(failed,why);}
  var p=SongProject.Load(projectFile);var rig=Rig.Load(p.Skeleton);var real=MotionClip.Load(p.Dance.Path);real.ValidateRig(rig);var before=SHA256.HashData(File.ReadAllBytes(p.Dance.Path));
  void Write(string path,Action<hkaAnimationContainer> configure){var f=MotionClip.Read(p.Dance.Path);configure(f.Container);using var stream=File.Create(path);new PackFileSerializer().Serialize(f.Root,new BinaryWriterEx(stream),f.Header);}
  hkaInterleavedUncompressedAnimation Make(){var poses=new List<Matrix4x4>();for(int frame=0;frame<8;frame++)for(int track=0;track<2;track++){float jump=frame==3?75:frame;poses.Add(new Pose(new(jump,track,frame*.2f),PoseEdits.Yaw(frame==3?140:frame*3),new Vector3(1+frame*.01f)).Matrix());}return new(){type=1,duration=2,numberOfTransformTracks=2,numberOfFloatTracks=1,transforms=poses,floats=Enumerable.Range(0,8).Select(i=>i==3?1f:0f).ToList(),annotationTracks=[new hkaAnnotationTrack{trackName="external-events",annotations=[new(){time=0,text="outside"},new(){time=.5f,text="same-time-A"},new(){time=.5f,text="same-time-B"},new(){time=1.5f,text="end"},new(){time=2,text="outside-end"}]}]};}
  void Single(hkaAnimationContainer c,hkaAnimation animation,short[]? map=null){c.animations=[animation];c.bindings=[new hkaAnimationBinding{animation=animation,originalSkeletonName=rig.Name,transformTrackToBoneIndices=(map??new short[]{4,97}).ToList(),floatTrackToFloatSlotIndices=[6]}];c.skeletons=[];}
  string synthetic=Path.Combine(output,"synthetic.hkx");Write(synthetic,c=>Single(c,Make()));var clip=MotionClip.Load(synthetic);clip.ValidateRig(rig);Check(clip.Tracks==2&&clip.FloatSamples.Length==8,"sparse uncompressed transforms and varying floats");
  var edit=new TrackEdit{In=.5,Out=1.5,Start=.25,Speed=2};string cropped=Path.Combine(output,"cropped.hkx");clip.Bake(cropped,edit,.25,.75,24,null,rig);var crop=MotionClip.Load(cropped);Check(crop.Animation.annotationTracks[0].annotations.Count==3,"two coincident start events and final boundary event retained");Check(crop.Animation.annotationTracks[0].annotations[0].text=="same-time-A"&&crop.Animation.annotationTracks[0].annotations[1].text=="same-time-B","event order and text preserved");Check(crop.Animation.annotationTracks[0].annotations[2].time==.5f,"event trim speed offset mapping");Check(crop.Container.bindings[0].floatTrackToFloatSlotIndices.SequenceEqual(new short[]{6}),"float binding retained");
  var observations=new List<object>();
  foreach(int fps in new[]{24,30,60,120}){string path=Path.Combine(output,$"synthetic-{fps}.hkx");clip.Bake(path,new TrackEdit{Out=2},0,2,fps,null,rig,new MotionCheckOptions{PositionWarning=.00001,RotationWarningDegrees=.00001});using var report=JsonDocument.Parse(File.ReadAllText(path+".verification.json"));var d=report.RootElement;Check(d.GetProperty("includesOutputMidpoints").GetBoolean()&&d.GetProperty("sampleCount").GetInt32()>(fps*2+1),"midpoints and source knots included");Check(d.GetProperty("warnings").GetArrayLength()>0,"off-grid rapid motion deviation detected");Check(d.GetProperty("floatWarning").GetBoolean(),"rapid variable Float error is reported");var result=MotionClip.Load(path);Check(Vector3.Distance(result.At(0)[0].T,clip.At(0)[0].T)<.001&&Vector3.Distance(result.At(2)[0].T,clip.At(2)[0].T)<.001,"start and end preserved");observations.Add(new{fps,report=JsonSerializer.Deserialize<JsonElement>(d.GetRawText())});}
  Check(MotionComparison.Angle(Quaternion.Identity,new Quaternion(0,0,0,-1))<1e-6,"quaternion sign changes are not rotation jumps");
  string broken=Path.Combine(output,"broken.hkx");Write(broken,c=>Single(c,Make(),[4]));Reject(()=>MotionClip.Load(broken),"partial binding not guessed");Write(broken,c=>Single(c,Make(),[4,4]));Reject(()=>MotionClip.Load(broken),"duplicate mapping rejected");Write(broken,c=>Single(c,Make(),[4,32767]));Reject(()=>MotionClip.Load(broken).ValidateRig(rig),"out of range mapping rejected");
  string implicitFile=Path.Combine(output,"implicit.hkx");Write(implicitFile,c=>Single(c,Make(),[]));Reject(()=>MotionClip.Load(implicitFile).World(rig,0),"implicit mapping without proof rejected");using(var stream=new MemoryStream(Rig.SourceBytes(p.Skeleton))){var skeleton=MotionClip.ReadStream(stream).Container.skeletons.First(x=>x.name==rig.Name);Write(implicitFile,c=>{Single(c,Make(),[]);c.skeletons=[skeleton];});}MotionClip.Load(implicitFile).ValidateRig(rig);Check(true,"implicit mapping supported when embedded hierarchy proves identity");
  string multi=Path.Combine(output,"multi.hkx");Write(multi,c=>{Single(c,Make());var other=Make();other.duration=3;c.animations.Add(other);c.bindings.Add(new(){animation=other,originalSkeletonName=rig.Name,transformTrackToBoneIndices=[4,97],floatTrackToFloatSlotIndices=[6]});});Reject(()=>MotionClip.Load(multi),"ambiguous animation selection required");var selected=MotionClip.Load(multi,1);Check(selected.AnimationIndex==1&&selected.Duration==3,"explicit binding selects linked animation");Reject(()=>selected.Bake(Path.Combine(output,"multi-out.hkx"),new(){Out=3},0,3,24),"complex output blocked without deleting other animations");
  Write(multi,c=>{Single(c,Make());var unused=Make();c.animations.Insert(0,unused);});Check(MotionClip.Load(multi).AnimationIndex==1,"unique binding selects linked animation rather than first");
  string root=Path.Combine(output,"root.hkx");Write(root,c=>{var a=Make();var type=typeof(hkaAnimation).Assembly.GetTypes().Single(t=>t.Name=="hkaDefaultAnimatedReferenceFrame");var reference=(hkaAnimatedReferenceFrame)Activator.CreateInstance(type)!;foreach(var prop in type.GetProperties()){if(prop.Name=="duration")prop.SetValue(reference,2f);else if(prop.Name=="referenceFrameSamples")prop.SetValue(reference,new List<Vector4>{Vector4.Zero,new(1,0,0,0)});else if(prop.Name=="up")prop.SetValue(reference,new Vector4(0,0,1,0));else if(prop.Name=="forward")prop.SetValue(reference,new Vector4(0,1,0,0));}a.extractedMotion=reference;Single(c,a);});var rootClip=MotionClip.Load(root);Check(rootClip.Animation.extractedMotion!=null,"synthetic root motion detected");string copy=Path.Combine(output,"root-copy.hkx");rootClip.Bake(copy,new(){Out=2},0,2,24);Check(File.ReadAllBytes(root).SequenceEqual(File.ReadAllBytes(copy)),"root full unedited pass-through is byte-identical");Reject(()=>rootClip.Bake(Path.Combine(output,"root-cut.hkx"),new(){In=.5,Out=2},0,1.5,24),"root trim is blocked");
  var reportUnknown=HkxDiagnostics.Inspect(broken,rig);Check(reportUnknown.Items.Any(x=>x.Status=="지원되지 않음"),"diagnostics preserve unsupported mapping information");File.WriteAllText(Path.Combine(output,"diagnostics.json"),HkxDiagnostics.Inspect(synthetic,rig).Json());
  var camera=MotionClip.Load(p.Camera.Path);var proposal=CameraAnalysis.Analyze(camera,rig);Check(proposal.Bone.HasValue&&camera.BoneMap.Contains(proposal.Bone.Value),"real camera candidate has bound track");var manual=SongProject.Load(projectFile);int selectedBone=proposal.Bone??throw new Exception("camera candidate missing");manual.CameraBone=selectedBone;manual.CameraBoneManual=true;manual.CameraForward="-X";manual.CameraForwardManual=true;manual.Save(Path.Combine(output,"manual-camera.danceproj"));var reload=SongProject.Load(Path.Combine(output,"manual-camera.danceproj"));Check(reload.CameraBone==manual.CameraBone&&reload.CameraForward=="-X"&&reload.CameraBoneManual&&reload.CameraForwardManual,"manual camera settings persist");
  var staticClip=new MotionClip{Duration=2,Tracks=1,BoneMap=[selectedBone],Samples=[new[]{rig.Reference[selectedBone]},new[]{rig.Reference[selectedBone]}]};Check(CameraAnalysis.Analyze(staticClip,rig).Bone==proposal.Bone,"static bound camera remains valid");
  string staticSource=Path.Combine(Path.GetDirectoryName(p.Dance.Path)!,"c10.hkx");var staticFloat=MotionClip.Load(staticSource);staticFloat.IdentityRigProof=staticFloat.MappingProofFor(rig);Check(staticFloat.Animation.numberOfFloatTracks==4&&staticFloat.FloatSamples.All(row=>row.All(v=>v==1)),"real spline static floats decoded");string staticOut=Path.Combine(output,"static-float.hkx");staticFloat.Bake(staticOut,new(){Out=2},0,2,24,null,rig);Check(MotionClip.Load(staticOut).Container.bindings[0].floatTrackToFloatSlotIndices.SequenceEqual(staticFloat.Container.bindings[0].floatTrackToFloatSlotIndices),"real static spline float bindings roundtrip");
  var splineFile=Path.Combine(output,"unsupported-spline-float.hkx");var splineData=MotionClip.Read(staticSource);var spline=(hkaSplineCompressedAnimation)splineData.Container.animations[0];spline.data[spline.numberOfTransformTracks*4]=0x80;using(var stream=File.Create(splineFile))new PackFileSerializer().Serialize(splineData.Root,new BinaryWriterEx(stream),splineData.Header);Reject(()=>MotionClip.Load(splineFile),"unverified spline float masks fail instead of zero substitution");var splineReport=HkxDiagnostics.Inspect(splineFile,rig);Check(splineReport.Items.Any(x=>x.Item.StartsWith("애니메이션"))&&splineReport.Items.Any(x=>x.Status=="지원되지 않음"),"unsupported float report retains original animation metadata");
  var mismatch=new Rig{Name=rig.Name,Names=rig.Names.ToArray(),Parents=rig.Parents.ToArray(),Reference=rig.Reference.ToArray(),FloatSlots=rig.FloatSlots.ToArray()};mismatch.Names[0]="different-root";Reject(()=>MotionClip.Load(implicitFile).ValidateRig(mismatch),"embedded skeleton name/order mismatch rejected");
  string additive=Path.Combine(output,"additive.hkx");Write(additive,c=>{Single(c,Make());var binding=c.bindings[0];var property=binding.GetType().GetProperty("blendHint")!;property.SetValue(binding,property.PropertyType.IsEnum?Enum.ToObject(property.PropertyType,1):Convert.ChangeType(1,property.PropertyType));});Reject(()=>MotionClip.Load(additive).World(rig,0),"additive standalone pose is not misread as absolute");
  Reject(()=>clip.Bake(synthetic,new(){Out=2},0,2,24),"original source path cannot be overwritten");Check(File.Exists(synthetic),"failed source overwrite preserves source");
  foreach(int fps in new[]{24,30,60,120}){string file=Path.Combine(output,$"camera-{fps}.hkx");camera.Bake(file,new(){In=30,Out=32},0,2,fps,null,rig);using var doc=JsonDocument.Parse(File.ReadAllText(file+".verification.json"));observations.Add(new{realCamera=true,selectedBone=proposal.Bone,fps,report=doc.RootElement.Clone()});Check(doc.RootElement.GetProperty("includesOutputMidpoints").GetBoolean(),"real camera midpoint verification");}
  string changed=Path.Combine(output,"changed.hkx");File.Copy(synthetic,changed,true);var snapshot=MotionClip.Load(changed);File.AppendAllText(changed,"changed");Reject(()=>snapshot.EnsureSourceUnchanged(),"changed source is rejected before export");
  string proofFile=Path.Combine(output,"proof.hkx");Write(proofFile,c=>Single(c,Make(),[]));var proofClip=MotionClip.Load(proofFile);string proof=proofClip.MappingProofFor(rig);proofClip.IdentityRigProof=proof;proofClip.ValidateRig(rig);Check(true,"explicit mapping proof accepted for exact source and rig");Write(proofFile,c=>{var a=Make();a.duration=3;Single(c,a,[]);});Reject(()=>MotionClip.Load(proofFile,null,proof).ValidateRig(rig),"mapping proof cannot transfer to changed source bytes");
  var missing=Path.Combine(output,"missing-skeleton.hkx");Check(Rig.ResolveReference(missing)!=Rig.BuiltinId,"missing custom skeleton never silently becomes builtin");Reject(()=>Rig.Load(missing),"missing custom skeleton requires explicit user choice");
  var packageProject=SongProject.Load(projectFile);packageProject.Camera=new(){Path=synthetic,Out=2};packageProject.CameraBone=97;packageProject.CameraBoneManual=true;packageProject.CameraForwardManual=true;packageProject.ExportOut=2;string packaged=GameExporter.Export(output,packageProject,real,clip,WaveAudio.Load(packageProject.Audio.Path),rig);var reference=MotionClip.Load(Path.Combine(packaged,"Diagnostics/camera.hkx.reference"));Check(reference.Animation.numberOfFloatTracks==1&&reference.Animation.annotationTracks[0].annotations.Count==5,"camera Float/Annotation data retained as non-executed reference HKX");Check(Directory.EnumerateFiles(packaged,"*.hkx",SearchOption.AllDirectories).Count()==2,"camera reference is not registered as an extra OAR animation");using(var doc=JsonDocument.Parse(File.ReadAllText(Path.Combine(packaged,"Diagnostics/camera-samples.verification.json")))){Check(doc.RootElement.GetProperty("includesOutputMidpoints").GetBoolean()&&doc.RootElement.GetProperty("floatTracksNotConsumedByCameraSamples").GetInt32()==1&&doc.RootElement.GetProperty("annotationEventsNotExecutedByCameraSamples").GetInt32()==5,"camera-sample data use and midpoint error explicitly reported");}
  var wrongCamera=SongProject.Load(projectFile);wrongCamera.ExportOut=2;wrongCamera.CameraBone=4;wrongCamera.CameraBoneManual=true;Reject(()=>GameExporter.Export(output,wrongCamera,real,camera,WaveAudio.Load(wrongCamera.Audio.Path),rig),"bound but far-off helper bone is not accepted as playable camera");
  string rootReport=Path.Combine(output,"root-diagnostics.json");File.WriteAllText(rootReport,HkxDiagnostics.Inspect(root,rig).Json());
  foreach(int fps in new[]{24,30,60,120}){string file=Path.Combine(output,$"Booo-{fps}.hkx");real.Bake(file,new(){In=30,Out=32,Start=0},0,2,fps,null,rig);using var doc=JsonDocument.Parse(File.ReadAllText(file+".verification.json"));observations.Add(new{realBooo=true,fps,report=doc.RootElement.Clone()});}
  string fullCopy=Path.Combine(output,"Booo-original-copy.hkx");real.Bake(fullCopy,new(){Out=real.Duration},0,real.Duration,24,null,rig);Check(File.ReadAllBytes(fullCopy).SequenceEqual(File.ReadAllBytes(p.Dance.Path)),"unedited full native-FPS motion preserves original compressed bytes");
  Check(before.SequenceEqual(SHA256.HashData(File.ReadAllBytes(p.Dance.Path))),"real Booo source unchanged");
  File.WriteAllText(Path.Combine(output,"error-comparisons.json"),JsonSerializer.Serialize(observations,SongProject.Json));
  File.WriteAllText(Path.Combine(output,"validation.json"),JsonSerializer.Serialize(new{passed=true,checks,sourceUnchanged=true,syntheticRootOnly=true,generalSplineFloatsSupported=false,multiplePreviewOnly=true,gameTested=false},SongProject.Json));
 }
}
